package io.github.rebrowser.bridge;
import static org.junit.Assert.*;
import io.github.rebrowser.music.MusicState;
import java.util.*;
import org.junit.Test;
public class ConnectorObservationsTest {
 static final String MUSIC="{\"account\":\"UNKNOWN\",\"playback\":\"UNKNOWN\",\"title\":\"x\",\"artist\":\"y\",\"positionMs\":null,\"durationMs\":null,\"rate\":null}";
 static final String MAIL="{\"account\":\"REPORTED_SIGNED_IN\",\"accountHint\":\"hint-not-account-proof\",\"messages\":[{\"id\":\"page-1\",\"subject\":\"subject\",\"sender\":\"display\",\"receivedUtcMs\":1,\"hasAttachment\":false}]}";
 @Test public void musicUnknownPositionRateRemainNullNotGuessedOneOrZero(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();MusicConnector.Observation o=new MusicConnector(f.lease).observe(f.result(MUSIC),1);assertNull(o.reportedPositionMs());assertNull(o.reportedDurationMs());assertNull(o.reportedRate());assertEquals(MusicState.Account.UNKNOWN,o.reportedAccount());}
 @Test public void playingIsReportedNotGuessedRateOrAuthentication(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();MusicConnector.Observation o=new MusicConnector(f.lease).observe(f.result(MUSIC.replace("\"playback\":\"UNKNOWN\"","\"playback\":\"PLAYING\"")),1);assertNull(o.reportedRate());assertEquals(MusicState.Account.UNKNOWN,o.reportedAccount());assertEquals(MusicState.Playback.PLAYING,o.reportedPlayback());}
 @Test public void musicShapeMissingUnknownAndWrongTypesReject(){for(String payload:Arrays.asList(MUSIC.replace("\"title\":\"x\",",""),MUSIC.replace("\"title\":\"x\"","\"title\":false"),MUSIC.replace("\"rate\":null","\"extra\":0,\"rate\":null"))){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();assertThrows(IllegalArgumentException.class,()->new MusicConnector(f.lease).observe(f.result(payload),1));}}
 @Test public void musicDurationPositionAndRateBoundsReject(){for(String payload:Arrays.asList(MUSIC.replace("\"positionMs\":null","\"positionMs\":-1"),MUSIC.replace("\"positionMs\":null","\"positionMs\":1.0"),MUSIC.replace("\"rate\":null","\"rate\":17"),MUSIC.replace("\"positionMs\":null","\"positionMs\":2").replace("\"durationMs\":null","\"durationMs\":1"))){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();assertThrows(IllegalArgumentException.class,()->new MusicConnector(f.lease).observe(f.result(payload),1));}}
 @Test public void reportedNativeTimeCannotMoveBackwards(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();MusicConnector c=new MusicConnector(f.lease);c.observe(f.result(MUSIC),2);assertThrows(IllegalArgumentException.class,()->c.observe(f.result(MUSIC),1));}
 @Test public void foreignPortCapsuleCannotRetargetMusicConsumer(){DocumentRouteTest.F f=new DocumentRouteTest.F(),g=new DocumentRouteTest.F();f.ready();g.ready();assertThrows(SecurityException.class,()->new MusicConnector(f.lease).observe(g.result(MUSIC),1));}
 @Test public void musicTextIsUtf8BoundedAndNoControlLogs(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();String big=new String(new char[200]).replace('\0','书');assertThrows(IllegalArgumentException.class,()->new MusicConnector(f.lease).observe(f.result(MUSIC.replace("\"title\":\"x\"","\"title\":\""+big+"\"")),1));}
 @Test public void mailSummaryClaimsNeverBecomeSqlAccountBindings(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();OutlookConnector.Observation o=new OutlookConnector(f.lease).observe(f.result(MAIL),1);assertEquals("hint-not-account-proof",o.unverifiedAccountHint());assertEquals("page-1",o.summaries().get(0).unverifiedPageId());assertFalse(o.summaries().get(0).reportedHasAttachment());assertThrows(UnsupportedOperationException.class,()->o.summaries().clear());}
 @Test public void mailUnknownOrSignedOutCannotCarryClaimedMailboxRows(){for(String state:new String[]{"UNKNOWN","REPORTED_SIGNED_OUT"}){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();assertThrows(IllegalArgumentException.class,()->new OutlookConnector(f.lease).observe(f.result(MAIL.replace("REPORTED_SIGNED_IN",state)),1));}}
 @Test public void mailDuplicateIdsAndUnknownFieldsReject(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();String row="{\"id\":\"page-1\",\"subject\":\"x\",\"sender\":\"x\",\"receivedUtcMs\":1,\"hasAttachment\":false}";String dup="{\"account\":\"REPORTED_SIGNED_IN\",\"accountHint\":\"x\",\"messages\":["+row+","+row+"]}";assertThrows(IllegalArgumentException.class,()->new OutlookConnector(f.lease).observe(f.result(dup),1));assertThrows(IllegalArgumentException.class,()->new OutlookConnector(f.lease).observe(f.result(MAIL.replace("\"subject\":\"subject\"","\"subject\":\"subject\",\"body\":\"not-admitted\"")),1));}
 @Test public void mailDateAndBooleanAreNotCoerced(){for(String payload:Arrays.asList(MAIL.replace("\"receivedUtcMs\":1","\"receivedUtcMs\":-1"),MAIL.replace("\"receivedUtcMs\":1","\"receivedUtcMs\":1.5"),MAIL.replace("\"hasAttachment\":false","\"hasAttachment\":0"))){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();assertThrows(IllegalArgumentException.class,()->new OutlookConnector(f.lease).observe(f.result(payload),1));}}
 @Test public void mailPageCannotExceedHundredRows(){StringBuilder rows=new StringBuilder();for(int i=0;i<101;i++){if(i>0)rows.append(',');rows.append("{\"id\":\"m").append(i).append("\",\"subject\":\"x\",\"sender\":\"x\",\"receivedUtcMs\":1,\"hasAttachment\":false}");}DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();String payload="{\"account\":\"REPORTED_SIGNED_IN\",\"accountHint\":\"x\",\"messages\":["+rows+"]}";assertThrows(IllegalArgumentException.class,()->new OutlookConnector(f.lease).observe(f.result(payload),1));}
 @Test public void wrongEvidenceAndAcceptedAreNotAnObservation(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();String bad=f.frame("RESULT","\"requestId\":\""+DocumentRouteTest.R+"\",\"outcome\":\"success\",\"evidenceKind\":\"command-accepted\",\"result\":"+MUSIC);DocumentLease.Received r=f.lease.receive(f.port,BridgeMessages.parse(bad));assertThrows(IllegalArgumentException.class,()->new MusicConnector(f.lease).observe(r,1));assertThrows(IllegalArgumentException.class,()->new MusicConnector(f.lease).observe(f.receive("ACCEPTED","\"requestId\":\""+DocumentRouteTest.R+"\""),1));}
 @Test public void nativeOutboundOnlyPromisesReadOnlyArgsAndNoAuthority(){DocumentRouteTest.F f=new DocumentRouteTest.F();f.ready();BridgeMessages.Command c=BridgeMessages.parse(BridgeMessages.nativeObserve(f.lease.nativeBinding(),DocumentRouteTest.R,MusicConnector.ACTION)).command();assertTrue(c.args().object().isEmpty());assertFalse(c.binding().isVerified());assertThrows(IllegalArgumentException.class,()->BridgeMessages.nativeObserve(f.lease.nativeBinding(),"bad","music.observe"));}
}
